mapper.select:
SELECT ACTIVE_COUNT AS activeCount,
QUEUE_SIZE AS queueSize,
COMPLETED_TASK_COUNT AS completedTaskCount,
REJECTED_TASK_COUNT AS rejectedTaskCount,
INSERT_TIME AS insertTime
FROM MONITOR_JAVA_THREAD_POOL_HISTORY
WHERE INSTANCE_ID = #{params.instanceId}

    AND `NAME` = #{params.threadPoolName}


    AND INSERT_TIME BETWEEN #{params.startTime} AND #{params.endTime}
